float musicalAccent(float value) {
 float activity=vrchReadSignal(0)+vrchReadSignal(1)+vrchReadSignal(2);
 float crisp=smoothstep(.02,.18,vrchReadSignal(2));
 return smoothstep(.005,.25,value)*mix(1.0,.12+.88*crisp,step(.001,activity));
}

float codeHash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float codeGlyph(vec2 uv,vec2 cell) {
 vec2 g=uv*vec2(3.0,5.0), index=floor(g), local=fract(g)-.5;
 float seed=codeHash(cell);
 float bit=step(.49,codeHash(index+cell*7.31));
 // Stable vertical stems and sparse crossbars read as glyphs at small output sizes.
 bit=max(bit*.75,step(abs(index.x-1.0),.1)*step(.25,seed));
 float mark=1.0-smoothstep(.23,.39,max(abs(local.x),abs(local.y)));
 vec2 inset=smoothstep(vec2(.06),vec2(.16),uv)*(1.0-smoothstep(vec2(.83),vec2(.94),uv));
 return bit*mark*inset.x*inset.y;
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;float aspect=iResolution.x/iResolution.y;
 float phase=vrchPhase_speed(), hit=musicalAccent(uParam_accent);
 vec3 color=vec3(.0015,.007,.0045);
 float deep=exp(-pow(abs((uv.x-.5)*1.3),2.0));
 color+=uParam_tint.rgb*.012*deep;
 for(int layer=0;layer<3;layer++) {
  float z=float(layer), cells=uParam_density*(.75+z*.50);
  vec2 grid=vec2(cells*aspect*.68,cells);
  vec2 g=uv*grid+vec2(z*8.31,0.0), id=floor(g), local=fract(g);
  float seed=codeHash(vec2(id.x,z*17.0));
  float velocity=.17+seed*.25+z*.06;
  float head=1.22-fract(phase*velocity+seed)*1.60;
  float behind=uv.y-head;
  float length=.25+uParam_trail*.73;
  float trail=step(0.0,behind)*exp(-max(behind,0.0)*4.8/length)*(1.0-smoothstep(length*.72,length,behind));
  float top=exp(-pow(abs(behind/(.75/cells)),2.0));
  float columnOn=smoothstep(.28+z*.12,.40+z*.12,codeHash(vec2(id.x+71.0,z+5.0)));
  float glyph=codeGlyph(local,id+vec2(z*32.0,0.0));
  float ambient=.005+uParam_depth*.018;
  float light=(ambient+trail*(.90+uParam_depth*.7)+top*2.4)*columnOn;
  vec3 green=uParam_tint.rgb/(1.0+z*1.35);
  vec3 headColor=mix(green,vec3(.75,1.0,.84),top*.82);
  color+=headColor*glyph*light*(.58+uParam_glow*.55)*(1.0+hit*top*.65);
  float beam=exp(-pow(abs((local.x-.5)*3.8),2.0))*trail*columnOn;
  color+=green*beam*(.016+uParam_glow*.018);
 }
 float vignette=1.0-.24*pow(length((uv-.5)*vec2(.9,1.0)),1.5);
 color*=vignette;
 fragColor=vec4(1.0-exp(-color*1.12),1.0);
}
